        "title": "ENUM, DOMAIN и пользовательские типы",
        "body": "ENUM позволяет определить ограниченный набор допустимых значений, например статусы заказа. Это помогает не допустить случайных вариантов вроде 'deliverd' и 'delivered'. Но изменение ENUM требует отдельной операции ALTER TYPE и должно учитываться при миграциях.\n\nDOMAIN создаёт именованный тип на основе существующего типа с дополнительными ограничениями. Например, домен для положительной суммы может переиспользоваться в нескольких таблицах. Это полезно, когда одно правило действительно общее.\n\nПользовательские составные типы объединяют несколько полей в один тип. Но не нужно создавать отдельный тип для каждого набора столбцов: иногда обычная таблица лучше, особенно если объект должен иметь собственный ключ и связи.",
