        "title": "IS DISTINCT FROM и сравнение с NULL",
        "body": "IS DISTINCT FROM — оператор PostgreSQL для сравнения с учётом NULL. В отличие от обычного <>, он всегда возвращает TRUE или FALSE: два NULL считаются одинаковыми, а NULL и обычное значение различными.\n\nЭто удобно, когда нужно найти строки, в которых значение отличается от заданного, включая ситуацию, когда одно из значений отсутствует. Оператор IS NOT DISTINCT FROM работает наоборот и полезен для NULL-безопасного равенства.\n\nОбычное сравнение a <> b при NULL возвращает UNKNOWN. Поэтому оно не выберет строку, где a отсутствует. IS DISTINCT FROM решает эту задачу без трёхзначной неопределённости.",
        "example": "SELECT order_id, employee_id\nFROM orders\nWHERE employee_id IS DISTINCT FROM 2\nORDER BY order_id;",
        "note": "IS DISTINCT FROM — PostgreSQL-расширение. Обычное <> сохраняет стандартное поведение UNKNOWN при NULL.",
