        "title": "Арифметика и операторные выражения",
        "body": "Арифметические выражения в SELECT позволяют вычислять новые значения из существующих столбцов. Для чисел доступны +, -, *, / и %. Например, количество умножается на цену, чтобы получить сумму позиции.\n\nВажно учитывать типы и деление. Если оба операнда целочисленные, целочисленное деление может отбросить дробную часть. Для точного денежного расчёта используй NUMERIC и контролируй округление.\n\nNULL распространяется через многие выражения: если цена отсутствует, quantity * price тоже будет NULL. Подменять неизвестную цену нулём можно только если это соответствует бизнес-смыслу.",
