        "title": "Числовые функции",
        "body": "Числовые функции выполняют округление и другие операции над числами. ROUND(value, scale) округляет до указанного количества знаков после запятой. CEIL округляет вверх до ближайшего целого, FLOOR — вниз. ABS возвращает абсолютное значение.\n\nОкругление результата и округление каждого слагаемого — разные действия. Например, сумма округлённых позиций может отличаться от округления общей суммы. В финансовой логике нужно заранее определить правило и применять его последовательно.\n\nДля NUMERIC округление десятичное и предсказуемое. Для DOUBLE PRECISION возможны эффекты двоичного представления, поэтому результат на границах округления может удивить.",
