        "title": "INNER JOIN и LEFT JOIN",
        "body": "INNER JOIN возвращает только строки, для которых нашлась пара по условию ON. LEFT JOIN сохраняет все строки слева; если справа пары нет, столбцы правой стороны заполняются NULL.\n\nЕсли заказ может быть без сотрудника, INNER JOIN удалит такой заказ из результата. LEFT JOIN сохранит его. Поэтому сначала реши бизнес-вопрос: нужен отчёт только по назначенным заказам или по всем заказам, включая неназначенные?\n\nУсловие ON определяет, какие строки справа считаются подходящими для соединения. WHERE фильтрует уже полученный результат. Например, LEFT JOIN с условием e.is_active в ON сохранит заказ без активного сотрудника, а фильтр e.is_active = TRUE в WHERE отбросит строки с NULL и фактически уберёт такие заказы.\n\nПосле LEFT JOIN NULL в правых столбцах может означать, что соответствующая строка не нашлась. Это не то же самое, что NULL в исходной таблице. Для проверки отсутствия пары используй ключ правой таблицы, который не допускает NULL, например e.employee_id IS NULL.",
