        "body": "SQL-клиент помогает подключаться к базе, изучать схему, выполнять запросы и просматривать результаты. Примеры: psql, DBeaver и DataGrip. BI-система, например Metabase, использует SQL для вопросов, графиков и дашбордов.\n\nBI-инструменты могут добавлять собственный синтаксис параметров, фильтров и шаблонов. Например, переменная в редакторе Metabase обрабатывается приложением до отправки запроса PostgreSQL. Поэтому запрос, который выглядит как SQL в BI, может не быть чистым SQL для psql.\n\nПроверяй тип подключения, схему, права, часовой пояс и переменные отчёта. Не путай настройки интерфейса BI с возможностями самой СУБД.",
