        "body": "Версия PostgreSQL влияет на доступные функции, синтаксис и поведение оптимизатора. Узнать её можно через version() или SHOW server_version. Документацию лучше открывать именно для той версии, с которой работаешь.\n\nПри поиске ошибки указывай СУБД, версию, полный текст ошибки и минимальный пример запроса. Убирай персональные данные и секреты из примера, но сохраняй структуру таблиц и типы столбцов.\n\nОфициальная документация — основной источник для точного синтаксиса и ограничений. Форумы полезны для контекста, но ответ для другой версии или другой СУБД может быть неприменим.",
