        "title": "Исследование неизвестной схемы",
        "body": "Если структура неизвестна, начни с каталога таблиц и столбцов. information_schema.tables покажет доступные таблицы, information_schema.columns — имена и типы столбцов. Затем изучи ограничения PK и FK, чтобы подтвердить связи.\n\nПосле структуры исследуй данные: количество строк, DISTINCT по ключам, долю NULL, диапазоны дат и примеры записей. Несколько строк помогают понять формат, но не доказывают общие правила. Проверяй распределения и ограничения, а не делай вывод по одному примеру.\n\nТолько после этого строй JOIN и метрики. Названия вроде user_id и order_id подсказывают возможную связь, но реальную кардинальность нужно подтвердить схемой и содержимым.",
