        "title": "Контроль результата: сверка и инварианты",
        "body": "Проверка результата нужна даже после успешного выполнения запроса. Сверь число строк, уникальность ключа, долю NULL, диапазоны дат и контрольные суммы. Для финансовых показателей полезно независимо пересчитать итог из другого зерна или источника.\n\nИнвариант — свойство, которое должно выполняться всегда или в рамках определённого набора данных. Например, число уникальных order_id не должно превышать число строк orders, а сумма платежей не должна неожиданно увеличиваться после JOIN с позициями.\n\nСохраняй контрольные запросы вместе с отчётом. Они помогают заметить изменения схемы, источника или логики после обновления данных.",
        "simple": "Корректность отчёта подтверждается контрольными проверками, а не только отсутствием SQL-ошибки.",
